void generateBinaryNumbers(int n, std::vector<std::string>& result) {
    if (n <= 0)
        return;

    for (int i = 0; i <= 1; i++) {
        std::string binary = std::to_string(i);
        result.push_back(binary);

        generateBinaryNumbers(n - 1, result);
    }
}

int main() {
    int n = 12; // Número de dígitos binários (12 para 111111111111)
    std::vector<std::string> binaryNumbers;

    generateBinaryNumbers(n, binaryNumbers);

    // Imprimir os números binários gerados
    for (const std::string& binary : binaryNumbers) {
        std::cout << binary << std::endl;
    }

    return 0;
}

