float media_pares(int *arr, int len)
{
  static int sum = 0, qnt = 0;
  if (!len)
    return 0;
  else
  {
    if (!(arr[len - 1] % 2))
    {
      sum += arr[len - 1];
      qnt++;
      media_pares(arr, len - 1);
    }
    else
      media_pares(arr, len - 1);
  }
  return (sum + 0.0) / qnt;
}

