char palavra[20] = {"Ola, Mundo!"};

void strToUpper(char palavra[]){
    int i = 0;
    while(palavra[i] != '\0'){
        if(palavra[i] >= 97 && palavra[i] <= 122){
            palavra[i] -= 32;
        }
        i++;
    }
}

void strToLower(char palavra[]){
    int i = 0;
    while(palavra[i] != '\0'){
        if(palavra[i] >= 65 && palavra[i] <= 90){
            palavra[i] += 32;
        }
        i++;
    }
}

int main(){
    printf("%s\n", palavra);

    // Maiuscula
    strToUpper(palavra);
    printf("%s\n", palavra);

    // Minuscula
    strToLower(palavra);
    printf("%s\n", palavra);

    return 0;
}

