/*função que retorna a soma de uma coluna da matriz*/
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int tam = 5;

int somaColuna(int m[][tam], int coluna){
    int soma = 0, l, c;

    for (l = 0; l < tam; l++){
        for (c = 0; c < tam; c++){
            if (c == coluna){
                soma += m[l][c];
            }
        }
    }
    return soma;
}


void imprimeMatriz(int m[][tam]){
    int l, c, coluna;
    printf("Matriz:\n\n");
    printf("  0   1   2   3   4\n\n");
