Na hora de "limpar" o buffer tem 3 maneiras:

1) scanf("%c");
2) setbuf(stdin,NULL);
3)scanf(" %25[^\n]", nomes[L]);  //Adicionar o espaço entre ...(" e %25[...  -> scanf("     %25[^\n]", nomes[L]

E.g.:

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define len 5

int main (void){
    
    char nomes[len][25]; //5 linhas e 25 colunas

    //Leitura
    for ( int L = 0 ; L < 5 ; L++){
        printf("Digite um nome (%d): ", L+1);
        scanf(" %25[^\n]", nomes[L]);
        //Caso ^ nao tenha esse espaco o o \n vai "sobrar" no buffer
        //e ele sera lido na segunda linha e o scanf encerra
        //Caso nao queria utiliza o espaco podemos ler nada e guardar em nada
        //Para retirar o enter do buffer:
        //scanf("%c");
        //setbuf(stdin,NULL);
    }

    //Impressao
    printf("\nLista dos nomes digitados: \n");
    for ( int i = 0 ; i < len ; i++){
        printf("Nome (%d): %s \n", i+1,nomes[i] );
    }


	return 0;
}

